'use strict';
const VEHICLES=[
 {id:'bicycle',name:'Coastline Bicycle',type:'Bicycle',price:900,minutes:8,energy:4,hunger:3,fuelUse:0,refuelRate:0,colour:'#849d71',description:'A simple city bicycle. No fuel, a little exercise, and a quicker way home.'},
 {id:'motorbike',name:'Sunbird Motorbike',type:'Motorbike',price:3200,minutes:5,energy:1,hunger:1,fuelUse:4,refuelRate:2,colour:'#c58768',description:'Light on its wheels. A nimble ride through Old Town’s busy crossings.'},
 {id:'car',name:'Kora Compact',type:'Car',price:8500,minutes:4,energy:0,hunger:1,fuelUse:6,refuelRate:3,colour:'#8caea6',description:'Four wheels, a little comfort, and a city that feels a bit more like yours.'}
];
function migrateVehicles(){const seen=new Set();state.vehicles=(Array.isArray(state.vehicles)?state.vehicles:[]).filter(v=>v&&VEHICLES.some(s=>s.id===v.id)&&!seen.has(v.id)&&seen.add(v.id)).map(v=>({id:v.id,fuel:v.id==='bicycle'?0:Math.max(0,Math.min(100,Math.floor(Number(v.fuel)||0)))}));if(state.activeTransport!=='walk'&&!state.vehicles.some(v=>v.id===state.activeTransport))state.activeTransport='walk';save();}
function getTravelPlan(destination){const here=destination===state.location;const spec=VEHICLES.find(v=>v.id===state.activeTransport),owned=state.vehicles?.find(v=>v.id===spec?.id);const reason=spec&&owned&&spec.fuelUse>owned.fuel?'Your tank is too low. Walking this trip; refill in Bay Rides.':'';const ride=spec&&owned&&!reason?spec:null;return {mode:ride?.id||'walk',name:ride?.type||'On foot',minutes:here?0:ride?.minutes||15,energy:here?0:ride?.energy??2,hunger:here?0:ride?.hunger??2,fuel:here?0:ride?.fuelUse||0,verb:ride?.id==='bicycle'?'Cycle':ride?.id==='motorbike'?'Ride':ride?.id==='car'?'Drive':'Walk',reason:here?'':reason};}
function buyVehicle(id){if(travelling)return {ok:false,message:'Finish your journey before buying a ride.'};const spec=VEHICLES.find(v=>v.id===id);if(!spec)return {ok:false,message:'Choose a ride from Bay Rides.'};if(state.vehicles.some(v=>v.id===id))return {ok:false,message:'You already own this ride. Choose it in your garage.'};if(state.money<spec.price)return {ok:false,message:`Save ${cash(spec.price-state.money)} more for the ${spec.name}.`};state.money-=spec.price;state.vehicles.push({id,fuel:spec.fuelUse?100:0});state.activeTransport=id;log(`Bought the ${spec.name} for ${cash(spec.price)}.`);save();render();return {ok:true,message:`The ${spec.name} is yours and selected. Pick a destination to take it out.`};}
function chooseTransport(id){if(travelling)return {ok:false,message:'Finish your journey before changing your ride.'};if(id!=='walk'&&!state.vehicles.some(v=>v.id===id))return {ok:false,message:'Buy this ride before choosing it.'};state.activeTransport=id;save();render();return {ok:true,message:id==='walk'?'A slower pace. You’ll walk to your next stop.':`${VEHICLES.find(v=>v.id===id).name} selected. Your next trip will use it.`};}
function refuelVehicle(id){if(travelling)return {ok:false,message:'Finish your journey before refuelling.'};const spec=VEHICLES.find(v=>v.id===id),owned=state.vehicles.find(v=>v.id===id);if(!spec||!owned||!spec.fuelUse)return {ok:false,message:'This ride does not need fuel.'};const amount=Math.min(25,100-owned.fuel),cost=amount*spec.refuelRate;if(!amount)return {ok:false,message:'Your tank is already full.'};if(state.money<cost)return {ok:false,message:`You need ${cash(cost)} to add ${amount}% fuel.`};state.money-=cost;owned.fuel+=amount;log(`Refuelled the ${spec.name}: +${amount}% fuel for ${cash(cost)}.`);save();render();return {ok:true,message:`Added ${amount}% fuel. Your tank is now ${owned.fuel}%.`};}
function vehicleArt(id){const body=id==='car'?'<ellipse cx="74" cy="94" rx="56" ry="10" fill="#47685b18"/><circle cx="44" cy="87" r="11" fill="#52695d"/><circle cx="111" cy="87" r="11" fill="#52695d"/><path d="M17 67 30 56h17l17-25h37l21 25 12 8v23H17z" fill="#92b3a8"/><path d="m56 55 14-18h27l15 18z" fill="#d4e4db"/><path d="M84 36v19M50 61v23M103 60v24" stroke="#789b8d" stroke-width="3"/><path d="M22 70h12M120 68h10" stroke="#efe7ba" stroke-width="5"/><circle cx="44" cy="87" r="5" fill="#cad7c7"/><circle cx="111" cy="87" r="5" fill="#cad7c7"/>':id==='motorbike'?'<ellipse cx="76" cy="98" rx="57" ry="7" fill="#4c6a5618"/><circle cx="39" cy="81" r="22" fill="#536957"/><circle cx="116" cy="81" r="22" fill="#536957"/><circle cx="39" cy="81" r="14" fill="#c6d4ba"/><circle cx="116" cy="81" r="14" fill="#c6d4ba"/><path d="m41 80 29-29h26l-4 31H58z" fill="#c48a6c"/><path d="m114 80-12-39-13-10M94 31h15" stroke="#697e60" stroke-width="6" fill="none"/><path d="M42 51h36" stroke="#6f7056" stroke-width="10" stroke-linecap="round"/><path d="m59 82 12-13h20" stroke="#8e654e" stroke-width="6" fill="none"/>':'<ellipse cx="76" cy="98" rx="59" ry="7" fill="#47664d18"/><circle cx="36" cy="79" r="23" stroke="#76886b" stroke-width="5" fill="#edf0df"/><circle cx="119" cy="79" r="23" stroke="#76886b" stroke-width="5" fill="#edf0df"/><path d="m36 79 25-42 23 42H36l53-37 30 37M86 29l9 27M87 29h16M60 37l-4-12" stroke="#91a77b" stroke-width="5" fill="none" stroke-linejoin="round"/><path d="M48 25h22" stroke="#85785c" stroke-width="6" stroke-linecap="round"/><circle cx="82" cy="79" r="6" fill="#718567"/>';return `<svg viewBox="0 0 152 112" class="vehicle-art" role="img" aria-label="${VEHICLES.find(v=>v.id===id)?.type||'Vehicle'}">${body}</svg>`;}
migrateVehicles();render();
